from config import *
import os
from omegaconf import OmegaConf
def main():
 assert not(E/'configs/protocol.json').exists()
 for p in ['configs','source','logs','data/raw','data/ABC/public/features','data/ABC/_private','data/D3/public/features','data/D3/_private','models','results']:(E/p).mkdir(parents=True,exist_ok=True)
 R.mkdir(parents=True,exist_ok=True);layouts=[];seeds=set();ids=set();sources={}
 def visit(x):
  if isinstance(x,list):
   for v in x:visit(v)
  elif isinstance(x,dict):
   if isinstance(x.get('layout'),dict)and all('block_'+c in x['layout']for c in COLORS):
    try:
     a=np.array([x['layout']['block_'+c]for c in COLORS],float)
     if a.shape==(3,6):layouts.append(a);seeds.add(x.get('seed'));ids.add(x.get('root_id'))
    except(ValueError,TypeError):pass
   for k,v in x.items():
    if k not in ['labels','results','predictions']and isinstance(v,(list,dict)):visit(v)
 for base in[P/'data',P/'experiments',P/'runs']:
  for folder,dirs,files in os.walk(base):
   dirs[:]=[d for d in dirs if d not in ['episodes','features','models','__pycache__']and Path(folder)/d!=E]
   for name in files:
    if name.endswith('.json')and'roots'in name:
     p=Path(folder)/name;sources[str(p)]=sha(p);visit(read(p))
 prior=len(layouts);roots=[]
 for env,n in [('A',2),('B',2),('C',4),('D',4)]:
  scene=P/f'vendor/calvin/calvin_env/conf/scene/calvin_scene_{env}.yaml';cfg=OmegaConf.load(scene);lo,hi=np.array(cfg.surfaces.table);sources[str(scene)]=sha(scene)
  for colour in COLORS:
   for rep in range(n):
    seed=16964000+len(roots);rid=f'{env}_intermediate_v3_{colour}_{rep}';assert seed not in seeds and rid not in ids;rng=np.random.default_rng(seed)
    for attempt in range(10000):
     arr=np.zeros((3,6));order=rng.permutation(3)
     for slot,j in enumerate(order):arr[j,:3]=[lo[0]+(hi[0]-lo[0])*(.14+.35*slot)+rng.uniform(-.012,.012),rng.uniform(lo[1]+.015,hi[1]-.015),.46];arr[j,5]=rng.uniform(-np.pi,np.pi)
     if not any(np.all(np.linalg.norm(arr[:,:3]-old[:,:3],axis=1)<.012)for old in layouts):break
    else:raise RuntimeError('Unique root budget exhausted')
    layouts.append(arr);roots.append({'root_id':rid,'environment':env,'split':'train'if env in 'AB'else'dev_select'if env=='C'and rep<2 else'dev_validate'if env=='C'else'test_D3','seed':seed,'target':colour,'replicate':rep,'layout':{'block_'+c:arr[j].tolist()for j,c in enumerate(COLORS)},'drawer_reset_m':0.,'branches':{'normal':['open_drawer',f'lift_{colour}_block_table','place_in_drawer','close_drawer'],'held_closed':[f'lift_{colour}_block_table','place_in_drawer','open_drawer','close_drawer']}})
 save(E/'configs/roots.json',roots);save(E/'configs/root_exclusion.json',{'prior_layout_declarations':prior,'roots':36,'sha256':sources,'rule':'At least one same-colour position differs by >=12mm from every declared previous/new layout. New seed and root ID. This screens repeated initial configurations, not proof of statistical independence.','generation_used_labels_or_predictions':False})
 protocol={'frozen_utc':now(),'scope':'One finite local data-coverage and prediction study. No task or planning evaluation. Same controller,6-skill canonical8D interface,9 propositions,vision/representation architecture,loss definitions and thresholds. No new dependencies, dataset uploads or cloud compute.','roots':{'A_train':6,'B_train':6,'C_select':6,'C_validate':6,'D3_test':12,'colours':'red,blue,pink balanced in every split','D3':'New root batch in same physical CALVIN D environment; not a new environment. Collect only after model/query/threshold selection sealed.'},'collection':{'branches_per_root':2,'resets':72,'max_skill_calls':288,'max_controls_per_skill':900,'posthold_controls':96,'reset_settle_controls':127,'max_control_steps':72*127+288*996,'internal_attempts_per_skill':2,'external_retries':0,'wall_minutes_soft_ceiling':90,'storage_soft_ceiling_GiB':5,'normal':'open,lift(target),place(no target),close. Stop after first non-success, count remaining as unreached.','held_closed':'lift(target),place,open,close. After a successful lift continue all3 calls even if refused; stop after failed physical call. No forced prerequisite repair.','reset':'Only native reset sets initial tabletop xyz/yaw and closed drawer; both branches share same declared layout/root. Reset is not an action transition. No teleport,attachment,force or nonrobot motor during calls.','recording':'Continuous dual-camera MP4 and full physical pose/contact/control trace every control; public RGB+15D proprio at boundaries, phase endpoints and before gripper changes. Records follow fixed phase events, not predicted/GT success selection. Failed/refused calls and unreached slots retained.','labels':'Unchanged contained_supported_drawer3_v2_1 using full quaternions,contacts,drawer geometry; validity masks. Uncertain never filled0. Private truth never model input.','root_boundary':'All branches,phase frames,and derived features remain in parent root split. No test material opened for training/selection.'},'query':{'fixed_model':'canonical_matched_seed0/update1000','original_head_reference':'query_seed0','architecture':'unchanged25473parameter Query','arms':['old_coverage','new_coverage'],'query_seeds':[0,1],'updates':1200,'batch':32,'sample_draws':38400,'checkpoints':[300,600,900,1200],'optimizer':'original AdamW lr.001 wd.001 clip1','normalization_and_class_weights':'reuse original query_seed0 AB normalization and original144-state weights, unchanged','shared_states':96,'old_arm_pool':'original144 AB budget','new_arm_pool':'same96 old plus up to48 new AB states: held_open,hover_above_drawer,post_place,held_closed once per root. Missing/unknown retained as missing/masked; no replacement collection.','batch_sampling':'same20 shared root-balanced draws; old12 original pool; new3 per each of4 coverage strata root-balanced. If a stratum has0 states stop/report instead of substitute.','selection':'Per arm/seed min .5 oldC-selection root-macro masked loss +.5 newC-select root-macro same loss; earlier tie. Then choose old/new arm per query seed by same C score for transition comparison; earlier arm in tie. Never C-validation or D.','other_state_retention':'old96 shared training and old C-validation116 retained in reporting. NewC-validation6 roots assessed once, never tuned.'},'transition':{'execute':'After query choices frozen, run one old/new transfer pair x2 sampler seeds, no joint query updates.','initial':'same fixed canonical_matched_seed0/update1000 in all4 runs','frozen':'DINO,registry,normalization,encoder,decoder,selected query perseed,thresholds','trainable':'transition only','updates':1000,'batch':64,'checkpoints':[0,250,500,750,1000],'optimizer':'existing AdamW lr.0001 wd.0001 clip5','loss':'unchanged equal4-group changed-weighted decoded feature error +.25 actual-successor latent MSE; every4 updates common-base observed2/3-step terms weighted.25, same existing implementation','sampling':'same48 oldAB root-balanced base; extra16 old or newAB. New12 normal-branch and4 held_closed-branch draws; old aux matched to same canonical skill distribution. No labels/native success in selection of draws.','selection':'minimum .5 oldC37-root-macro existing feature error +.5 newC-select6-root-macro feature error; earlier checkpoint. No semantic or test score for selection.','budget':'4x1000 updates,256000 sample draws; no further adjustment or third arm.'},'evaluation':{'normal_primary':True,'refusal_separate':True,'paths':['true-state readout','true-previous-state one-step','recursive1..4skills from initial only'],'metrics':'full9 exact correctness only where all9valid; validity-masked and perHolding/In/drawer separately; fixed complete-root cohort plus all-available denominators; same-trajectory proposition pairing of actual-readout correctness vs prediction correctness; original latentMSE supplementary, not semantic metric.','D3_opening':'all chosen models sealed before collection/opening; report one new evaluation, after which this batch is seen. No test-driven resampling,thresholding,reselection or repair.','comparison':'First all query heads under original fixed transition; then old/new transitions under same C-selected query within seed. Never credit joint changes as one cause.','media':'show fixed first colour-stratified C root examples of above-drawer held vs after release; D examples only descriptive after freeze.'},'estimate':{'collection_minutes':[10,20],'whole_study_minutes':[30,60],'basis':'previous same-machine4skill records ~7sec before denser physical recording; allow overhead and analysis. Estimates only.'}}
 save(E/'configs/protocol.json',protocol)
 paths=list((E/'source').glob('*.py'))+[E/'configs/protocol.json',E/'configs/roots.json',P/'src/wm_symbolic/physical_oracle.py',P/'src/wm_symbolic/env_adapter.py',P/'scripts/evaluate_physical_oracle.py',REP/'source/labels_v2_1.py',REP/'models/canonical_matched_seed0/update1000.pt',REP/'models/query_seed0.pt']
 save(E/'configs/collection_frozen.json',{'frozen_utc':now(),'sha256':{str(p):sha(p)for p in paths}})
 (R/'PROTOCOL.md').write_text('# 有限补数与预测评测协议\n\n36根：A/B训练各6根，C选择/验证各6根，同环境D的新根12个；三色均衡。每根两次原生复位和两条最多4技能记录，共72复位、最多288技能调用。900控制步/技能、96步稳定等待、内部最多2次尝试、外部0次重试。失败/拒绝/未达全部保留。完整姿态和接触用于原9命题真值，未知掩码。\n\n先固定编码器与转移，做原覆盖/新增覆盖查询头对照，各2种子、1200更新、38400抽样；旧状态保留96个共享样本。C选择后冻结查询头，再固定它及编码器，仅以原/新增A/B转移做等预算预测器对照，各2种子、1000更新、64000抽样。结构、损失及阈值不变。\n\n全部模型选择与文件哈希在D采集前封存。D只进行真实读出、单步与1–4技能递归预测，不运行规划/任务评测。测试看过后明确成为已见批次。详细不可变字段见实验configs/protocol.json，采集源码哈希见collection_frozen.json。\n')
 print('PROTOCOL_FROZEN roots36 episodes72 calls_max288',flush=True)
if __name__=='__main__':main()
